import math

def check_condition(n):
    """Checks if k^2 == 1 (mod n) for all k coprime to n."""
    if n < 2:
        return True

    for k in range(1, n):
        if math.gcd(k, n) == 1:
            if (k * k) % n != 1:
                return False, k
    return True, None

results = {}
first_counterexample = None

print("--- Testing n from 2 to 20 ---")
for n in range(2, 21):
    is_valid, counterexample_k = check_condition(n)
    results[n] = is_valid

    if not is_valid and first_counterexample is None:
        first_counterexample = (n, counterexample_k)
        print(f"*** Found First Counterexample at n={n} with k={counterexample_k} ***")

    status = "PASS" if is_valid else f"FAIL (Counterexample k={counterexample_k})"
    print(f"n={n:2}: {status}")

print("\n--- Summary ---")
print(f"Results dictionary: {results}")
if first_counterexample:
    n_ce, k_ce = first_counterexample
    print(f"First Counterexample Found: n={n_ce}, k={k_ce}")
else:
    print("No counterexample found in the range 2 <= n <= 20.")

